FUNC = 'def _pdf_literal(value):\n    raw = str(value).encode("latin-1", "replace")\n    return b"(" + raw.replace(b"\\\\", b"\\\\\\\\").replace(b"(", b"\\\\(").replace(b")", b"\\\\)") + b")"\n\n\ndef _jpeg_size(raw):\n    if not raw.startswith(b"\\xff\\xd8"):\n        return None\n    index = 2\n    while index + 9 < len(raw):\n        if raw[index] != 0xFF:\n            return None\n        marker = raw[index + 1]\n        if marker in (0xC0, 0xC1, 0xC2):\n            height = int.from_bytes(raw[index + 5:index + 7], "big")\n            width = int.from_bytes(raw[index + 7:index + 9], "big")\n            return width, height\n        if marker in (0xD8, 0xD9):\n            index += 2\n            continue\n        length = int.from_bytes(raw[index + 2:index + 4], "big")\n        if length < 2:\n            return None\n        index += 2 + length\n    return None\n\n\ndef _photo_jpeg(conn, school_code, uid):\n    root = Path(conn.execute("PRAGMA database_list").fetchone()[2]).resolve().parent\n    if root.name != "DEVELOPMENT_SUBJECT_WIZARD":\n        return None\n    folder = (root / "school_photos" / school_code).resolve()\n    path = (folder / (str(uid) + ".jpg")).resolve()\n    if path.parent != folder or not path.is_file():\n        return None\n    raw = path.read_bytes()\n    return raw if _jpeg_size(raw) else None\n\n\ndef _printing_jobs(conn):\n    rows = conn.execute(\n        """SELECT o.id, o.job_code, o.school_code, COUNT(s.id)\n        FROM school_delivery_orders o\n        JOIN school_delivery_slots s ON s.order_id = o.id\n        WHERE o.status=\'PRINTING\' AND o.want_cards=1\n        GROUP BY o.id\n        ORDER BY o.id"""\n    ).fetchall()\n    jobs = []\n    for order_id, job_code, school_code, slots in rows:\n        if not slots or slots % SHEET_SIZE:\n            continue\n        pages = slots // SHEET_SIZE\n        if pages > MAX_BATCH_PAGES:\n            raise ValueError(job_code + " has more than 25 pages")\n        jobs.append((order_id, job_code, school_code, pages))\n    return jobs\n\n\ndef _pack_jobs(jobs):\n    batches = []\n    current = []\n    pages = 0\n    for job in jobs:\n        if current and pages + job[3] > MAX_BATCH_PAGES:\n            batches.append(current)\n            current = []\n            pages = 0\n        current.append(job)\n        pages += job[3]\n    if current:\n        batches.append(current)\n    return batches\n\n\ndef _batch_cards(conn, order_id, school_code, job_code):\n    school = conn.execute(\n        "SELECT school_name, city FROM school_accounts WHERE school_code=?",\n        (school_code,),\n    ).fetchone()\n    slots = conn.execute(\n        """SELECT position, student_uid, class_name, student_name\n        FROM school_delivery_slots WHERE order_id=? ORDER BY position""",\n        (order_id,),\n    ).fetchall()\n    cards = []\n    for position, uid, class_name, student_name in slots:\n        extra = conn.execute(\n            "SELECT father_name FROM school_students WHERE school_code=? AND student_uid=?",\n            (school_code, uid),\n        ).fetchone()\n        cards.append({\n            "school": school[0] if school else school_code,\n            "city": school[1] if school else "",\n            "job": job_code,\n            "name": student_name,\n            "father": extra[0] if extra else "",\n            "class_name": class_name,\n            "uid": uid,\n            "place": ((position - 1) % SHEET_SIZE) + 1,\n            "jpeg": _photo_jpeg(conn, school_code, uid),\n        })\n    return [cards[index:index + SHEET_SIZE] for index in range(0, len(cards), SHEET_SIZE)]\n\n\ndef _pdf_document(pages):\n    objects = []\n\n    def add(body):\n        objects.append(body)\n        return len(objects)\n\n    font_id = add(b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>")\n    page_ids = []\n    for cards in pages:\n        commands = []\n        images = []\n        card_w = 85 * 72 / 25.4\n        card_h = 54 * 72 / 25.4\n        gap = 2 * 72 / 25.4\n        margin = 8 * 72 / 25.4\n        page_h = 841.89\n        for index, card in enumerate(cards):\n            col = index % 2\n            row = index // 2\n            x = margin + col * (card_w + gap)\n            y = page_h - margin - (row + 1) * card_h - row * gap\n            commands.append("%.2f %.2f %.2f %.2f re S" % (x, y, card_w, card_h))\n            image = card["jpeg"]\n            text_x = x + 6\n            if image:\n                width, height = _jpeg_size(image)\n                header = (\n                    "<< /Type /XObject /Subtype /Image /Width %d /Height %d "\n                    "/ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length %d >>\\nstream\\n"\n                    % (width, height, len(image))\n                ).encode("ascii")\n                images.append(add(header + image + b"\\nendstream"))\n                commands.append("q 62 0 0 78 %.2f %.2f cm /Im%d Do Q" % (x + 4, y + 16, len(images) - 1))\n                text_x = x + 72\n            else:\n                commands.append("BT /F1 8 Tf %.2f %.2f Td %s Tj ET" % (x + 4, y + 40, _pdf_literal("NO PHOTO").decode("latin-1")))\n\n            def line(size, dy, value):\n                commands.append(\n                    "BT /F1 %d Tf %.2f %.2f Td %s Tj ET" % (size, text_x, y + dy, _pdf_literal(value).decode("latin-1"))\n                )\n\n            line(8, card_h - 14, card["school"][:40])\n            line(8, card_h - 26, card["job"] + "  " + card["city"][:16])\n            line(11, card_h - 44, card["name"][:26])\n            line(9, card_h - 58, ("Father: " + card["father"])[:32])\n            line(9, card_h - 72, "Class " + card["class_name"][:12])\n            line(9, card_h - 86, card["uid"])\n            line(8, 8, "Place %d" % card["place"])\n        content = "\\n".join(commands).encode("latin-1", "replace")\n        content_id = add(b"<< /Length %d >>\\nstream\\n" % len(content) + content + b"\\nendstream")\n        xobject = " ".join("/Im%d %d 0 R" % (number, image_id) for number, image_id in enumerate(images))\n        page_ids.append(add(\n            b"<< /Type /Page /Parent 0 0 R /MediaBox [0 0 595.28 841.89] /Contents %d 0 R /Resources << /Font << /F1 %d 0 R >> /XObject << %s >> >> >>" % (\n                content_id, font_id, xobject.encode("ascii")\n            )\n        ))\n    kids = " ".join("%d 0 R" % page_id for page_id in page_ids)\n    pages_id = add(("<< /Type /Pages /Count %d /Kids [%s] >>" % (len(page_ids), kids)).encode("ascii"))\n    catalog_id = add(("<< /Type /Catalog /Pages %d 0 R >>" % pages_id).encode("ascii"))\n    fixed = []\n    for body in objects:\n        fixed.append(body.replace(b"/Parent 0 0 R", ("/Parent %d 0 R" % pages_id).encode("ascii")))\n    output = bytearray(b"%PDF-1.4\\n")\n    offsets = [0]\n    for number, body in enumerate(fixed, 1):\n        offsets.append(len(output))\n        output += ("%d 0 obj\\n" % number).encode("ascii") + body + b"\\nendobj\\n"\n    xref = len(output)\n    output += ("xref\\n0 %d\\n" % (len(fixed) + 1)).encode("ascii")\n    output += b"0000000000 65535 f \\n"\n    for offset in offsets[1:]:\n        output += ("%010d 00000 n \\n" % offset).encode("ascii")\n    output += ("trailer<< /Size %d /Root %d 0 R >>\\nstartxref\\n%d\\n%%%%EOF" % (len(fixed) + 1, catalog_id, xref)).encode("ascii")\n    return bytes(output)\n\n\ndef _batch_folder(conn):\n    root = Path(conn.execute("PRAGMA database_list").fetchone()[2]).resolve().parent\n    if root.name != "DEVELOPMENT_SUBJECT_WIZARD":\n        raise ValueError("Refused: batches can be written only in the development copy")\n    folder = (root / "print_batches").resolve()\n    if folder.parent != root:\n        raise ValueError("Refused")\n    return folder\n\n\ndef _write_batches(conn):\n    jobs = _printing_jobs(conn)\n    if not jobs:\n        raise ValueError("No ID-card job is in Printing. Start printing first.")\n    folder = _batch_folder(conn)\n    folder.mkdir(exist_ok=True)\n    stamp = datetime.now().strftime("%Y%m%d")\n    for old in folder.glob("BATCH-" + stamp + "-*.pdf"):\n        if old.is_file() and old.parent == folder:\n            old.unlink()\n    made = []\n    for number, batch in enumerate(_pack_jobs(jobs), 1):\n        pages = []\n        for order_id, job_code, school_code, _count in batch:\n            pages.extend(_batch_cards(conn, order_id, school_code, job_code))\n        if len(pages) > MAX_BATCH_PAGES:\n            raise ValueError("Batch exceeded 25 pages")\n        name = "BATCH-%s-%02d.pdf" % (stamp, number)\n        path = (folder / name).resolve()\n        if path.parent != folder:\n            raise ValueError("Refused")\n        path.write_bytes(_pdf_document(pages))\n        made.append((name, len(pages), len(batch)))\n    return made\n\n\ndef _batch_links(conn):\n    try:\n        folder = _batch_folder(conn)\n    except ValueError:\n        return ""\n    if not folder.is_dir():\n        return "<p>No combined PDF yet.</p>"\n    names = sorted(path.name for path in folder.glob("BATCH-*.pdf") if path.is_file() and path.parent == folder)\n    if not names:\n        return "<p>No combined PDF yet. Only jobs in Printing are included.</p>"\n    return "<p>Combined PDFs: " + " ".join(\n        \'<a href="/saini-queue?pdf=%s">%s</a>\' % (_esc(name), _esc(name)) for name in names\n    ) + "</p>"\n\n\ndef _send_batch_pdf(conn, name):\n    if len(name) != 20 or not name.startswith("BATCH-") or not name.endswith(".pdf"):\n        raise ValueError("Unknown batch file")\n    stamp = name[6:14]\n    seq = name[15:17]\n    if not stamp.isdigit() or not seq.isdigit() or name[14] != "-":\n        raise ValueError("Unknown batch file")\n    folder = _batch_folder(conn)\n    path = (folder / name).resolve()\n    if path.parent != folder or not path.is_file():\n        raise ValueError("Batch file not found")\n    from flask import Response\n    return Response(\n        path.read_bytes(),\n        mimetype="application/pdf",\n        headers={"Content-Disposition": "inline; filename=\\"%s\\"" % name},\n    )\n\n\n'
A_OLD = 'SHEET_SIZE = 10\n'
A_NEW = 'SHEET_SIZE = 10\nMAX_BATCH_PAGES = 25\n'
C_OLD = '                if action == "approve_payment":\n                    paid = approve_payment(conn, int(request.form.get("payment_id", "0")))\n                    notice = "Payment approved. Rs %d deducted from the school balance." % paid\n                else:\n'
C_NEW = '                if action == "approve_payment":\n                    paid = approve_payment(conn, int(request.form.get("payment_id", "0")))\n                    notice = "Payment approved. Rs %d deducted from the school balance." % paid\n                elif action == "combine":\n                    made = _write_batches(conn)\n                    notice = "Combined %d PDF files. Each file has at most 25 pages. A job is never split." % len(made)\n                else:\n'
D_OLD = '    job_text = (request.args.get("job") or "").strip()\n'
D_NEW = '    pdf_name = (request.args.get("pdf") or "").strip()\n    if request.method == "GET" and pdf_name:\n        try:\n            return _send_batch_pdf(conn, pdf_name)\n        except ValueError as exc:\n            error = str(exc)\n    job_text = (request.args.get("job") or "").strip()\n'
