E_NEW = '    filters += "</p>"\n    batch_form = (\n        \'<form method="post"><input type="hidden" name="csrf_token" value="\' + _esc(token) + \'">\'\n        + \'<input type="hidden" name="action" value="combine">\'\n        + \'<button type="submit">Combine printing jobs</button></form>\'\n        + "<p>Only jobs in Printing. One PDF stops at 25 pages. A 2-page job stays together. The rest go into the next file.</p>"\n        + _batch_links(conn)\n    )\n'
F_OLD = '+ filters + flag + pay_table'
F_NEW = '+ filters + batch_form + flag + pay_table'

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def once(text, old, new, name):
    if text.count(old) != 1:
        raise SystemExit("ABORT " + name)
    return text.replace(old, new, 1)

def main():
    if sha(ORIG) != AH or sha(DB) != BH:
        raise SystemExit("ABORT ORIGINAL")
    raw = MOD.read_bytes()
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if "def _write_batches" in text or "Combine printing jobs" in text:
        raise SystemExit("ABORT ALREADY")
    text = once(text, A_OLD, A_NEW, "LIMIT")
    text = once(text, "def saini_queue(get_db, request, session):\n", FUNC + "def saini_queue(get_db, request, session):\n", "FUNC")
    text = once(text, C_OLD, C_NEW, "ACTION")
    text = once(text, D_OLD, D_NEW, "DOWNLOAD")
    text = once(text, E_OLD, E_NEW, "FORM")
    text = once(text, F_OLD, F_NEW, "SHOW")
    if text.count("MAX_BATCH_PAGES = 25") != 1 or text.count("def _pack_jobs") != 1:
        raise SystemExit("ABORT RESULT")
    newline = "\r\n" if b"\r\n" in raw else "\n"
    tmp = MOD.with_name("school_delivery.combine_tmp")
    pyc = MOD.with_name("school_delivery.combine_tmp.pyc")
    tmp.write_bytes(text.replace("\n", newline).encode("utf-8"))
    try:
        py_compile.compile(str(tmp), cfile=str(pyc), doraise=True)
    finally:
        if pyc.exists():
            pyc.unlink()
    BAK.mkdir(parents=True, exist_ok=True)
    (BAK / "school_delivery_before_combine.py").write_bytes(raw)
    MOD.write_bytes(tmp.read_bytes())
    tmp.unlink()
    if sha(ORIG) != AH or sha(DB) != BH:
        raise SystemExit("ABORT ORIGINAL_CHANGED")
    print("PATCH_OK")
    print("max_pages=25")
    print("job_not_split=yes")
    print("original_app=" + sha(ORIG))
    print("original_db=" + sha(DB))
    print("activation_changed=no")

if __name__ == "__main__":
    main()
